"use strict";window.Download=function(n){var t="data:"+n.mimeType+";base64,"+n.byteArray;fetch(t).then(function(n){return n.blob()}).then(function(t){var i=window.document.createElement("a");i.href=window.URL.createObjectURL(t,{type:n.mimeType});i.download=n.fileName;document.body.appendChild(i);i.click();document.body.removeChild(i)})};window.ScrollToBottom=function(n){var t=document.getElementById(n);t.scrollTop=t.scrollHeight-t.clientHeight};window.PlayAudio=function(n){document.getElementById(n).play()};